[FunctionName("ChatWithDocs")]
public static async Task<IActionResult> Run(
    [HttpTrigger(AuthorizationLevel.Function, "post")] HttpRequest req,
    ILogger log)
{
    var request = await req.ReadFromJsonAsync<ChatRequest>();

    // 1. Embed user query
    var embedding = await _openAI.GetEmbeddingAsync(request.Message);

    // 2. Search documentation
    var searchResults = await _search.SearchAsync(embedding, top: 3);

    // 3. Build prompt with context
    var prompt = $"Context: {string.Join("\n", searchResults)}\n\nQuestion: {request.Message}\n\nAnswer:";

    // 4. Generate response
    var response = await _openAI.GetChatCompletionAsync(prompt);

    // 5. Store conversation
    await _cosmosDb.SaveAsync(new ChatMessage { ... });

    return new OkObjectResult(new { Answer = response, Sources = searchResults });
}
